    document["paths"]["/api/v2/migu/tasks/{batch_id}"] = nlohmann::json::parse(R"transferjson({"get":{"tags":["migu"],"summary":"Get persistent transfer operation","description":"Available in maintenance and legacy mode with compatible schema. Real operation IDs return target tasks and direct child IDs; aggregate state includes controlled producer/child work through at most two levels. Destination counts describe direct file tasks. A legacy batch ID, including a caller-supplied ID of up to 128 bytes, returns the immutable old-view state plus all real operation_ids, without pretending a multi-operation batch is one operation. Use real IDs for v2 stop or the old stop endpoint for a legacy batch.","parameters":[{"name":"batch_id","in":"path","required":true,"schema":{"type":"string","maxLength":128}}],"responses":{"200":{"description":"Operation and per-target tasks.","content":{"application/json":{"schema":{"oneOf":[{"$ref":"#/components/schemas/V2TransferOperation"},{"$ref":"#/components/schemas/V2LegacyBatchMapping"}]}}}},"400":{"description":"Invalid or unknown fields; no operation accepted.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}},"404":{"description":"Operation not found.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}},"500":{"description":"Persistence failed.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}},"503":{"description":"Mode, target, schema or maintenance unavailable; an uncertain commit must be reconciled with the same idempotency key.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}}}}})transferjson");
