    document["paths"]["/api/v2/migu/settings"] = nlohmann::json::parse(R"transferjson({"get":{"tags":["migu"],"summary":"Read transfer budgets and safe target status","description":"Credentials, absolute paths, remote aliases and fingerprint material are omitted. Concurrency and verification policy are startup-only. Legacy write projection is currently unavailable in parallel mode.","responses":{"200":{"description":"Safe settings snapshot.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/V2TransferSettings"}}}},"500":{"description":"Persistence failed.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}},"503":{"description":"Mode, target, schema or maintenance unavailable; an uncertain commit must be reconciled with the same idempotency key.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}}}},"patch":{"tags":["migu"],"summary":"Replace budget for one enabled target","description":"All four policy fields are required to avoid read/merge races. Applies only to subsequently accepted operations, without modifying queued/running tasks, private configuration or strict verification policy.","requestBody":{"required":true,"content":{"application/json":{"schema":{"$ref":"#/components/schemas/V2TransferSettingsPatch"}}}},"responses":{"200":{"description":"Updated future acceptance budget.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/V2TransferSettingsUpdated"}}}},"400":{"description":"Invalid or unknown fields; no operation accepted.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}},"500":{"description":"Persistence failed.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}},"503":{"description":"Mode, target, schema or maintenance unavailable; an uncertain commit must be reconciled with the same idempotency key.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}}}}})transferjson");
    document["paths"]["/api/v2/migu/tasks/{batch_id}/producers"] = nlohmann::json::parse(R"transferjson({"get":{"tags":["migu"],"summary":"Read independent durable producer plans","description":"Reads only the requested real operation, including waiting_input, failed and child-operation identity. Does not fetch content. Available in maintenance and legacy mode with compatible schema. Inspect related child operations separately.","parameters":[{"name":"batch_id","in":"path","required":true,"schema":{"type":"string","maxLength":64}}],"responses":{"200":{"description":"Frozen producer plans.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/V2ProducerPage"}}}},"400":{"description":"Invalid request.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}},"404":{"description":"Operation not found.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}},"500":{"description":"Persistence unavailable.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}},"503":{"description":"Schema, maintenance or runtime unavailable.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}}}}})transferjson");
    document["paths"]["/api/v2/migu/producers/retry"] = nlohmann::json::parse(R"transferjson({"post":{"tags":["migu"],"summary":"Explicitly retry one durable producer","description":"Requires parallel mode and write admission; preserves original source/target/processor versions. This is acceptance only. Does not recover a still-running claim or recreate the parent transfer.","requestBody":{"required":true,"content":{"application/json":{"schema":{"$ref":"#/components/schemas/V2ProducerRetry"}}}},"responses":{"202":{"description":"Retry durably accepted.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/V2ProducerRetryAccepted"}}}},"400":{"description":"Invalid request.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}},"409":{"description":"Original producer cannot be retried in its current state or versions.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}},"500":{"description":"Persistence unavailable.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}},"503":{"description":"Schema, maintenance or runtime unavailable.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}}}}})transferjson");
