    document["components"]["schemas"]["V2TransferTask"] = nlohmann::json::parse(R"transferjson({"type":"object","additionalProperties":false,"required":["task_id","owner_type","resource_id","destination","adapter","state","result_code","content_generation","target_revision","cancel_requested","busy_task_id","attempt_count","policy","strict_sha256"],"properties":{"task_id":{"type":"integer","minimum":1},"owner_type":{"type":"string","enum":["song","singer","album","song_artifact"]},"resource_id":{"type":"integer","minimum":1},"destination":{"type":"string","enum":["local","baidu","gdrive"]},"adapter":{"type":"string"},"state":{"type":"string"},"result_code":{"type":"string"},"content_generation":{"type":"integer","minimum":0},"target_revision":{"type":"integer","minimum":0},"cancel_requested":{"type":"boolean"},"busy_task_id":{"type":"integer","minimum":0,"nullable":true},"attempt_count":{"type":"integer","minimum":0},"policy":{"$ref":"#/components/schemas/V2TransferPolicy"},"strict_sha256":{"type":"boolean"}}})transferjson");
    document["components"]["schemas"]["V2TransferOperation"] = nlohmann::json::parse(R"transferjson({"type":"object","additionalProperties":false,"required":["batch_id","state","logical_resource_count","destination_counts","tasks","replayed","parent_batch_id","parent_task_id","child_batch_ids"],"properties":{"batch_id":{"type":"string"},"state":{"type":"string"},"logical_resource_count":{"type":"integer","minimum":0},"destination_counts":{"type":"object","additionalProperties":{"type":"object","additionalProperties":{"type":"integer","minimum":0}}},"tasks":{"type":"array","items":{"$ref":"#/components/schemas/V2TransferTask"},"maxItems":600},"replayed":{"type":"boolean"},"parent_batch_id":{"type":"string","nullable":true},"parent_task_id":{"type":"integer","minimum":1,"nullable":true},"child_batch_ids":{"type":"array","items":{"type":"string"},"maxItems":600}}})transferjson");
    document["components"]["schemas"]["V2TransferStop"] = nlohmann::json::parse(R"transferjson({"type":"object","additionalProperties":false,"required":["batch_id"],"properties":{"batch_id":{"type":"string","minLength":1,"maxLength":64,"pattern":"^[a-z0-9_]+$"},"destinations":{"type":"array","items":{"type":"string","enum":["local","baidu","gdrive"]},"maxItems":3,"uniqueItems":true}}})transferjson");
    document["components"]["schemas"]["V2CloudReceipt"] = nlohmann::json::parse(R"transferjson({"type":"object","additionalProperties":false,"required":["id","owner_type","resource_id","provider","adapter","task_state","content_generation","target_revision","current_content_generation","current_target_revision","size_bytes","checksum","verification","verification_method","uploaded_at","verified_at","result_code","path_resolved","current","matches_local","transfer_skipped","assumed_stored"],"properties":{"id":{"type":"integer","minimum":1},"owner_type":{"type":"string","enum":["song","singer","album","song_artifact"]},"resource_id":{"type":"integer","minimum":1},"provider":{"type":"string","enum":["baidu","gdrive"]},"adapter":{"type":"string"},"task_state":{"type":"string"},"content_generation":{"type":"integer","minimum":0},"target_revision":{"type":"integer","minimum":0},"current_content_generation":{"type":"integer","minimum":0},"current_target_revision":{"type":"integer","minimum":0},"size_bytes":{"type":"integer","minimum":0},"checksum":{"type":"string"},"verification":{"type":"string","enum":["unverified","operator_attested","object_observed","hash_matched","sha256_verified","conflict"]},"verification_method":{"type":"string"},"uploaded_at":{"type":"integer","minimum":0,"nullable":true},"verified_at":{"type":"integer","minimum":0,"nullable":true},"result_code":{"type":"string"},"path_resolved":{"type":"boolean"},"current":{"type":"boolean","description":"Confirmed version and content evidence match persistent state and any configured strict verification requirement; without a configured target profile only persistent evidence is evaluated. Does not probe remote availability."},"matches_local":{"type":"boolean","nullable":true},"transfer_skipped":{"type":"boolean"},"assumed_stored":{"type":"boolean"}}})transferjson");
