    document["components"]["schemas"]["V2TransferSettingsPatch"] = nlohmann::json::parse(R"transferjson({"type":"object","additionalProperties":false,"required":["destination","policy"],"properties":{"destination":{"type":"string","enum":["local","baidu","gdrive"]},"policy":{"$ref":"#/components/schemas/V2TransferPolicy"}}})transferjson");
    document["components"]["schemas"]["V2TransferSettingsUpdated"] = nlohmann::json::parse(R"transferjson({"type":"object","additionalProperties":false,"required":["destination","policy","applies_to"],"properties":{"destination":{"type":"string","enum":["local","baidu","gdrive"]},"policy":{"$ref":"#/components/schemas/V2TransferPolicy"},"applies_to":{"type":"string","enum":["new_operations"]}}})transferjson");
    document["components"]["schemas"]["V2TransferSettings"] = nlohmann::json::parse(R"transferjson({"type":"object","additionalProperties":false,"required":["mutable","readonly"],"properties":{"mutable":{"type":"object","additionalProperties":false,"required":["targets"],"properties":{"targets":{"type":"array","items":{"$ref":"#/components/schemas/V2TransferSettingsPatch"},"maxItems":3}}},"readonly":{"type":"object","additionalProperties":false,"required":["pipeline_mode","targets","legacy_write_projection_ready"],"properties":{"pipeline_mode":{"type":"string","enum":["legacy","parallel"]},"targets":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["destination","adapter","available","verification_policy"],"properties":{"destination":{"type":"string","enum":["local","baidu","gdrive"]},"adapter":{"type":"string"},"available":{"type":"boolean"},"verification_policy":{"type":"string","enum":["hash_match","strict_sha256"]}}},"maxItems":3},"legacy_write_projection_ready":{"type":"boolean"}}}}})transferjson");
